package com.railflow.yardops.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="operational_alerts") public class OperationalAlert { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private String type; private String message; private String entityReference; @Enumerated(EnumType.STRING) private AlertSeverity severity; @Enumerated(EnumType.STRING) private AlertStatus status=AlertStatus.OPEN; private Instant createdAt=Instant.now(); protected OperationalAlert(){} public OperationalAlert(String type,String message,String entityReference,AlertSeverity severity){this.type=type;this.message=message;this.entityReference=entityReference;this.severity=severity;} public UUID getId(){return id;} public String getType(){return type;} public String getMessage(){return message;} public String getEntityReference(){return entityReference;} public AlertSeverity getSeverity(){return severity;} public AlertStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public void acknowledge(){status=AlertStatus.ACKNOWLEDGED;} public void resolve(){status=AlertStatus.RESOLVED;} }